    assignmentGroup: (AssignmentGroup | null)
    assignmentGroupId: (Scalars['ID'] | null)
    assignmentOverrides: (AssignmentOverrideConnection | null)
    assignmentTargetConnection: (AssignmentOverrideConnection | null)
    /** Discriminator indicating the actual type of this assignment */
    assignmentType: AssignmentTypeEnum
    /** Returns empty array if visible to everyone */
    assignmentVisibility: (Scalars['ID'][] | null)
    /**
     * @deprecated Use autoGradeEligibility instead
     * Errors related to the assignment
     */
    autoGradeAssignmentErrors: Scalars['String'][]
    /**
     * @deprecated Use autoGradeEligibility instead
     * Issues related to the assignment
     */
    autoGradeAssignmentIssues: (EligibilityIssue | null)
    /** Eligibility for auto-grading */
    autoGradeEligibility: (AutoGradeEligibility | null)
    canDuplicate: (Scalars['Boolean'] | null)
    canManageAssignTo: (Scalars['Boolean'] | null)
    canUnpublish: (Scalars['Boolean'] | null)
    /** specifies that the current user can update the rubric self-assessment. */
    canUpdateRubricSelfAssessment: (Scalars['Boolean'] | null)
    /** A list of checkpoints (also known as sub_assignments) that are associated with this assignment */
    checkpoints: (Checkpoint[] | null)
    course: (Course | null)
    courseId: (Scalars['ID'] | null)
    createdAt: (Scalars['DateTime'] | null)
    description: (Scalars['String'] | null)
    discussion: (Discussion | null)
    /** when this assignment is due */
    dueAt: (Scalars['DateTime'] | null)
    dueDateRequired: (Scalars['Boolean'] | null)
    expectsExternalSubmission: (Scalars['Boolean'] | null)
    expectsSubmission: (Scalars['Boolean'] | null)
    /** specifies that students are being graded as a group (as opposed to being graded individually). */
    gradeAsGroup: Scalars['Boolean']
    gradeByQuestionEnabled: Scalars['Boolean']
    /** If this is a group assignment, boolean flag indicating whether or not students will be graded individually. */
    gradeGroupStudentsIndividually: (Scalars['Boolean'] | null)
    graded: (Scalars['Boolean'] | null)
    /** If true, the assignment has at least one graded submission */
    gradedSubmissionsExist: (Scalars['Boolean'] | null)
    /** Grader identities if moderated assignment */
    graderIdentitiesConnection: (GraderIdentityConnection | null)
    gradesPublished: (Scalars['Boolean'] | null)
    gradesPublishedAt: (Scalars['String'] | null)
    gradingPeriodId: (Scalars['String'] | null)
    /** The grading role of the current user for this assignment. Returns null if the user does not have sufficient grading permissions. */
    gradingRole: (GradingRole | null)
    gradingStandard: (GradingStandard | null)
    gradingStandardId: (Scalars['ID'] | null)
    gradingType: (GradingType | null)
    groupCategoryId: (Scalars['Int'] | null)
    groupSet: (GroupSet | null)
    /** returns submissions grouped to one submission object per group */
    groupSubmissionsConnection: (SubmissionConnection | null)
    /** specifies that this assignment is a group assignment */
    hasGroupCategory: Scalars['Boolean']
    hasMultipleDueDates: (Scalars['Boolean'] | null)
    /** Indicates if the assignment has LTI 2.0 plagiarism detection tool configured */
    hasPlagiarismTool: Scalars['Boolean']
    hasRubric: Scalars['Boolean']
    /** Boolean: returns true if the assignment is checkpointed. A checkpointed assignment has checkpoints ( also known as sub_assignments) */
    hasSubAssignments: Scalars['Boolean']
    /** If true, the assignment has been submitted to by at least one student */
    hasSubmittedSubmissions: (Scalars['Boolean'] | null)
    htmlUrl: (Scalars['URL'] | null)
    id: Scalars['ID']
    importantDates: (Scalars['Boolean'] | null)
    inClosedGradingPeriod: (Scalars['Boolean'] | null)
    isLockedByMasterCourse: Scalars['Boolean']
    /** Assignment is connected to a New Quiz */
    isNewQuiz: Scalars['Boolean']
    /** the lock date (assignment is locked after this date) */
    lockAt: (Scalars['DateTime'] | null)
    lockInfo: (LockInfo | null)
    ltiAssetProcessorsConnection: (LtiAssetProcessorConnection | null)
    moderatedGrading: (ModeratedGrading | null)
    moderatedGradingEnabled: (Scalars['Boolean'] | null)
    moduleItems: (ModuleItem[] | null)
    modules: (Module[] | null)
    muted: (Scalars['Boolean'] | null)
    /** submissions for sub-assignments belonging to the current user */
    mySubAssignmentSubmissionsConnection: (SubmissionConnection | null)
    name: (Scalars['String'] | null)
    needsGradingCount: (Scalars['Int'] | null)
    newQuizzesAnonymousParticipants: (Scalars['Boolean'] | null)
    nonDigitalSubmission: (Scalars['Boolean'] | null)
    /** If true, the assignment will be omitted from the student's final grade */
    omitFromFinalGrade: (Scalars['Boolean'] | null)
    /**
     * specifies that this assignment is only assigned to students for whom an
     *        `AssignmentOverride` applies.
     */
    onlyVisibleToOverrides: Scalars['Boolean']
    originalityReportVisibility: (Scalars['String'] | null)
    /** The parent assignment (only for PeerReviewSubAssignment) */
    parentAssignment: (Assignment | null)
    /** The parent assignment ID (only for PeerReviewSubAssignment) */
    parentAssignmentId: (Scalars['ID'] | null)
    peerReviewSubAssignment: (PeerReviewSubAssignment | null)
    peerReviews: (PeerReviews | null)
    /** the assignment is out of this many points */
    pointsPossible: (Scalars['Float'] | null)
    /** determines the order this assignment is displayed in in its assignment group */
    position: (Scalars['Int'] | null)
    postManually: (Scalars['Boolean'] | null)
    postPolicy: (PostPolicy | null)
    /** present if Sync Grades to SIS feature is enabled */
    postToSis: (Scalars['Boolean'] | null)
    /** Indicates if the user is locked out of provisional grading for this assignment. */
    provisionalGradingLocked: Scalars['Boolean']
    published: (Scalars['Boolean'] | null)
    quiz: (Quiz | null)
    /** Is the current user restricted from viewing quantitative data */
    restrictQuantitativeData: (Scalars['Boolean'] | null)
    rubric: (Rubric | null)
    rubricAssessment: (AssignmentRubricAssessment | null)
    rubricAssociation: (RubricAssociation | null)
    /** specifies that students can self-assess using the assignment rubric. */
    rubricSelfAssessmentEnabled: (Scalars['Boolean'] | null)
    rubricUpdateUrl: (Scalars['String'] | null)
    scheduledPost: (ScheduledPost | null)
    scoreStatistic: (AssignmentScoreStatistic | null)
    sisId: (Scalars['String'] | null)
    state: AssignmentState
    submissionTypes: (SubmissionType[] | null)
    /** submissions for this assignment */
    submissionsConnection: (SubmissionConnection | null)
    submissionsDownloads: (Scalars['Int'] | null)
    supportsGradeByQuestion: Scalars['Boolean']
    /** internal use */
    suppressAssignment: Scalars['Boolean']
    timeZoneEdited: (Scalars['String'] | null)
    title: (Scalars['String'] | null)
    totalGradedSubmissions: (Scalars['Int'] | null)
    totalSubmissions: (Scalars['Int'] | null)
    type: (Scalars['String'] | null)
    /** the unlock date (assignment is unlocked after this date) */
